def load() -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    path = 'data/environment/input/monthly_precipitations_ashburnham.csv'
    df = pd.read_csv(path)

    # Keep only 4-digit years
    df['Year'] = df['Year'].astype(str).str.strip()
    df = df[df['Year'].str.fullmatch(r'\d{4}')].copy()
    df['Year'] = df['Year'].astype(int)

    month_cols = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

    def to_num(s):
        if pd.isna(s):
            return np.nan
        s = str(s).strip()
        if s in ['M', '']:
            return np.nan
        if s == 'T':
            return 0.0
        return pd.to_numeric(s, errors='coerce')

    for c in month_cols:
        df[c] = df[c].map(to_num)

    return df[['Year'] + month_cols]

